// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    bool public reentered;
    bool public reentrySucceeded;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            try c.Collect(0) {
                reentrySucceeded = true;
            } catch {
                reentrySucceeded = false;
            }
        }
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, c.MinSum(), 100 ether);

        vm.deal(address(this), amount);
        vm.prank(address(this));
        c.Put{value: amount}(0);

        vm.warp(block.timestamp + 1);

        reentered = false;
        reentrySucceeded = false;

        vm.prank(address(this));
        c.Collect(amount);

        assertTrue(!reentrySucceeded);
    }
}
